// routing arrows — is the hard part of a general renderer. We sidestep it by
// only handling the shape that is already linear: there is exactly one path,
// so the order is unambiguous and the rendering is trivial and always
// correctly aligned.
package mermaidascii

import (
	"regexp"
	"strings"

	"github.com/mattn/go-runewidth"
)

// node is a flowchart vertex: a stable id and a human label (defaults to the
// id when the node is referenced without bracketed text).
type node struct {
	id    string
	label string
}

// edge is a directed link from one node id to another, with an optional
// label parsed from `-->|label|` syntax.
type edge struct {
	from  string
	to    string
	label string
}

// linkRe matches a Mermaid link operator with an optional `|label|`. The
// surrounding whitespace is consumed so the text between matches is exactly
// the node tokens. Inline-label syntax (`A -- text --> B`) is intentionally
// unsupported and causes a parse failure → raw fallback.
var linkRe = regexp.MustCompile(`\s*(?:-->|---|==>|===|-\.->|-\.-)\s*(?:\|([^|]*)\|)?\s*`)

// nodeRe matches a single node token: an id followed by an optional shape
// wrapper. We extract the id and the inner label regardless of shape, and
// always render a rectangle.
var nodeRe = regexp.MustCompile(`^([A-Za-z0-9_]+)\s*(\[\[.*\]\]|\(\(.*\)\)|\[.*\]|\(.*\)|\{.*\}|>.*\])?$`)

// headerRe matches the `flowchart`/`graph` declaration line.
var headerRe = regexp.MustCompile(`^(?:flowchart|graph)\b`)

// RenderFlowchart renders src as an aligned Unicode box diagram and returns
// ok=true, or returns ok=false when src is not a single linear chain it can
// render. On ok=false the caller should show the raw Mermaid source.
func RenderFlowchart(src string) (string, bool) {
	nodes, edges, ok := parse(src)
	if !ok {
		return "", false
	}
	order, ok := linearOrder(nodes, edges)
	if !ok {
		return "", false
	}
	return render(order, edges), true
}

// parse reads the flowchart body into nodes and edges. It returns ok=false
// for any construct outside the supported subset (subgraphs, `&` multi-edge,
// non-flowchart diagrams, or any unrecognized non-blank line).
func parse(src string) (map[string]*node, []edge, bool) {
	nodes := map[string]*node{}
	var order []string // first-seen id order, for stable node bookkeeping
	var edges []edge
	sawFlowchart := false
	sawAnyContent := false

	ensure := func(id, label string) {
		n, exists := nodes[id]
		if !exists {
			nodes[id] = &node{id: id, label: label}
			order = append(order, id)
			return
		}
