		label := ""
		if loc[2] >= 0 {
			label = strings.TrimSpace(line[loc[2]:loc[3]])
		}
		labels = append(labels, label)
		prev = loc[1]
	}
	// Trailing node after the last link.
	n, ok := parseNodeToken(line[prev:])
	if !ok {
		return nil, nil, false
	}
	tokens = append(tokens, n)

	edges := make([]edge, 0, len(tokens)-1)
	for i := 0; i+1 < len(tokens); i++ {
		edges = append(edges, edge{from: tokens[i].id, to: tokens[i+1].id, label: labels[i]})
	}
	return tokens, edges, true
}

// parseNodeToken extracts the id and label from a single node token, peeling
// the shape wrapper (`[]`, `()`, `{}`, `(())`, `[[]]`, `>]`). Returns
// ok=false on anything that isn't a lone node reference.
func parseNodeToken(s string) (node, bool) {
	s = strings.TrimSpace(s)
	m := nodeRe.FindStringSubmatch(s)
	if m == nil {
