	var start string
	sources := 0
	for id := range nodes {
		if indeg[id] == 0 {
			sources++
			start = id
		}
	}
	if sources != 1 {
		return nil, false
	}

	// Walk the unique path; it must visit every node exactly once.
	order := make([]node, 0, len(nodes))
	seen := map[string]bool{}
	for cur := start; ; {
		if seen[cur] {
			return nil, false // cycle
		}
		seen[cur] = true
		order = append(order, *nodes[cur])
		next, ok := outTo[cur]
		if !ok {
			break
		}
		cur = next
	}
	if len(order) != len(nodes) {
		return nil, false // disconnected
	}
	return order, true
}

// render draws the ordered chain as three aligned rows: box tops, box
// middles (with connecting arrows), and box bottoms. edges supplies the
// per-link labels, looked up by the (from,to) of consecutive nodes.
func render(order []node, edges []edge) string {
	labelFor := func(from, to string) string {
		for _, e := range edges {
			if e.from == from && e.to == to {
				return e.label
			}
		}
		return ""
	}

	var top, mid, bot strings.Builder
	for i, n := range order {
		if i > 0 {
			conn := connector(labelFor(order[i-1].id, n.id))
			pad := strings.Repeat(" ", runewidth.StringWidth(conn))
			top.WriteString(pad)
			mid.WriteString(conn)
			bot.WriteString(pad)
		}
